type bundleCommand struct{}

func newBundleCommand() *cobra.Command {
	bundle := &bundleCommand{}

	cmd := &cobra.Command{
		Use:   "bundle",
		Short: "Manage Flipt bundles",
	}

	cmd.AddCommand(&cobra.Command{
		Use:   "build [flags] <name>",
